BEGIN;
CREATE TABLE IF NOT EXISTS knowledge_uploads (id uuid PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, mime text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes > 0), content_hash text NOT NULL, storage_path text NOT NULL, status text NOT NULL CHECK(status IN ('queued','processing','ready','failed','cancelled')), error_code text, document_id uuid, started_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_documents (id uuid PRIMARY KEY, user_id bigint REFERENCES users(id) ON DELETE CASCADE, product_verified boolean NOT NULL DEFAULT false, name text NOT NULL, mime text NOT NULL, content_hash text NOT NULL, status text NOT NULL CHECK(status IN ('queued','processing','ready','failed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), CHECK ((user_id IS NOT NULL) <> product_verified));
CREATE TABLE IF NOT EXISTS knowledge_chunks (id bigserial PRIMARY KEY, document_id uuid NOT NULL REFERENCES knowledge_documents(id) ON DELETE CASCADE, user_id bigint REFERENCES users(id) ON DELETE CASCADE, product_verified boolean NOT NULL, ordinal integer NOT NULL, content text NOT NULL, content_hash text NOT NULL, embedding vector(1536) NOT NULL, embedding_model text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,ordinal), CHECK ((user_id IS NOT NULL) <> product_verified));
CREATE INDEX IF NOT EXISTS knowledge_chunks_user_idx ON knowledge_chunks(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS knowledge_chunks_fts_idx ON knowledge_chunks USING gin(to_tsvector('simple',content));
CREATE TABLE IF NOT EXISTS research_requests (id uuid PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, conversation_id text NOT NULL, agent_id text NOT NULL, query text NOT NULL, status text NOT NULL CHECK(status IN ('queued','processing','completed','failed','cancelled')), report_id uuid, error_code text, started_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE research_requests ADD COLUMN IF NOT EXISTS error_code text;
CREATE TABLE IF NOT EXISTS research_reports (id uuid PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, conversation_id text NOT NULL, summary text NOT NULL, confidence real NOT NULL, checked_at timestamptz NOT NULL, report_json jsonb NOT NULL, status text NOT NULL CHECK(status IN ('completed','failed','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN ALTER TABLE research_requests ADD CONSTRAINT research_requests_report_fk FOREIGN KEY(report_id) REFERENCES research_reports(id) ON DELETE SET NULL; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS research_sources (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES research_reports(id) ON DELETE CASCADE, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, url text NOT NULL, canonical_url text NOT NULL, domain text NOT NULL, title text NOT NULL, author text, published_at timestamptz, retrieved_at timestamptz NOT NULL, content_hash text NOT NULL, content_type text NOT NULL, language text NOT NULL, relevance real NOT NULL, quality real NOT NULL, status text NOT NULL, UNIQUE(report_id,canonical_url));
CREATE TABLE IF NOT EXISTS research_claim_sources (id bigserial PRIMARY KEY, report_id uuid NOT NULL REFERENCES research_reports(id) ON DELETE CASCADE, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id uuid NOT NULL REFERENCES research_sources(id) ON DELETE CASCADE, claim text NOT NULL, evidence_quote text NOT NULL, evidence_start integer NOT NULL, evidence_end integer NOT NULL, evidence_hash text NOT NULL, contradiction text);
CREATE INDEX IF NOT EXISTS research_requests_user_idx ON research_requests(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS research_reports_user_idx ON research_reports(user_id,created_at DESC);
INSERT INTO schema_migrations(version) VALUES('051_knowledge_research') ON CONFLICT DO NOTHING;
COMMIT;
